setupSQL:
CREATE SCHEMA cssql_oracle; CREATE TABLE cssql_oracle.analytics_retained_state(id integer PRIMARY KEY, region text, person text, channel text, amount double precision);
    INSERT INTO cssql_oracle.analytics_retained_state SELECT -id,'A',CASE WHEN id % 2 = 0 THEN 'a' ELSE 'b' END,'keep',10 FROM generate_series(1,9) AS input(id);
    INSERT INTO cssql_oracle.analytics_retained_state VALUES (-10,'B','b','keep',100),(-11,'C','b','keep',100),(-12,'C','c','keep',100),
      (-13,'Z',NULL,'keep',NULL),(-14,NULL,'c','keep',50),(-15,'clipped','x','exclude',999),(-16,'A','b','keep',NULL);
    INSERT INTO cssql_oracle.analytics_retained_state SELECT id, LPAD(id::text,8,'0'),id::text,'keep',1 FROM generate_series(1,60001) AS input(id);
